#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=7

SCRIPT_DIR=$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd)
REPOSITORY_ROOT=$(cd -- "$SCRIPT_DIR/.." && pwd)
RESULT_ROOT="$REPOSITORY_ROOT/artifacts/ticket-13/manual"
SESSION_ID="${SESSION_ID:-win10-$(date +%Y%m%d)}"
ENV_FILE="$RESULT_ROOT/manual-qualification-$SESSION_ID.env"
RESULTS_TSV="$RESULT_ROOT/manual-qualification-$SESSION_ID.tsv"
PICKER_EXECUTABLE="$REPOSITORY_ROOT/artifacts/foundation/picker-win-x64/ModernEmojiPicker.exe"
REPORT_WRITER="$SCRIPT_DIR/write-manual-qualification-report.ps1"
NETWORK_OBSERVER="$SCRIPT_DIR/observe-manual-runtime-network.ps1"
TEST_PAGE="$RESULT_ROOT/manual-target-$SESSION_ID.html"
TEST_TEXT="$RESULT_ROOT/manual-target-$SESSION_ID.txt"
monitor_pid=""

cleanup_manual_session() {
  if [[ -n "$monitor_pid" ]] && kill -0 "$monitor_pid" >/dev/null 2>&1; then
    kill "$monitor_pid" >/dev/null 2>&1 || true
    wait "$monitor_pid" 2>/dev/null || true
  fi
}
trap cleanup_manual_session EXIT

mkdir -p "$RESULT_ROOT"
if [[ ! -f "$RESULTS_TSV" ]]; then
  printf 'Stage\tCaseId\tCase\tResult\tNotes\tEvidence\n' > "$RESULTS_TSV"
fi

single_line() {
  local value="$1"
  value=${value//$'\t'/ }
  value=${value//$'\r'/ }
  value=${value//$'\n'/ }
  printf '%s' "$value"
}

remove_existing_case() {
  local case_id="$1" temporary
  temporary=$(mktemp)
  awk -F '\t' -v id="$case_id" 'NR == 1 || $2 != id' "$RESULTS_TSV" > "$temporary"
  mv "$temporary" "$RESULTS_TSV"
}

record_case() {
  local stage_number="$1" case_id="$2" case_name="$3" evidence="$4"
  local existing result_key result notes
  existing=$(awk -F '\t' -v id="$case_id" 'NR > 1 && $2 == id { print $4; exit }' "$RESULTS_TSV")
  if [[ -n "$existing" ]]; then
    say "$case_name — มีผลเดิม: $existing"
    if confirm "เก็บผลเดิมของกรณีนี้ไว้หรือไม่?"; then
      return
    fi
    remove_existing_case "$case_id"
  fi

  while true; do
    printf '  %sเลือกผล%s [p=ผ่าน, f=ไม่ผ่าน, u=ทำไม่ได้ใน environment, s=ยังไม่ทดสอบ]: ' "$BOLD" "$RESET"
    read -r result_key || true
    case "$result_key" in
      p|P) result="ผ่าน"; break ;;
      f|F) result="ไม่ผ่าน"; break ;;
      u|U) result="ทำไม่ได้ใน environment"; break ;;
      s|S) result="ยังไม่ทดสอบ"; break ;;
      *) warn "กรุณาเลือก p, f, u หรือ s" ;;
    esac
  done

  printf '  %sหมายเหตุ%s (เว้นว่างได้เมื่อผ่าน): ' "$BOLD" "$RESET"
  read -r notes || true
  printf '%s\t%s\t%s\t%s\t%s\t%s\n' \
    "$stage_number" \
    "$(single_line "$case_id")" \
    "$(single_line "$case_name")" \
    "$(single_line "$result")" \
    "$(single_line "$notes")" \
    "$(single_line "$evidence")" >> "$RESULTS_TSV"
  printf '  %s✓ บันทึกผล%s %s\n' "$GREEN" "$RESET" "$case_name"
}

save_stage_evidence() {
  local key="$1" prompt="$2"
  ask "$key" "$prompt"
  write_env "$key" "${!key}"
}

ensure_picker_running() {
  if ! MSYS2_ARG_CONV_EXCL='*' tasklist.exe /FI "IMAGENAME eq ModernEmojiPicker.exe" 2>/dev/null | grep -qi 'ModernEmojiPicker.exe'; then
    "$PICKER_EXECUTABLE" >/dev/null 2>&1 &
    disown || true
    sleep 2
  fi
}

assert_non_elevated_shell() {
  local elevated
  elevated=$(powershell.exe -NoProfile -NonInteractive -Command \
    '$principal = [Security.Principal.WindowsPrincipal]::new([Security.Principal.WindowsIdentity]::GetCurrent()); if ($principal.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)) { "true" } else { "false" }' \
    | tr -d '\r')
  if [[ "$elevated" == "true" ]]; then
    warn "terminal นี้เปิดแบบ Administrator ทำให้แอปทดสอบมีสิทธิ์สูงกว่า Modern Emoji Picker และให้ผลลวงว่า Win + . ใช้งานไม่ได้"
    say "ปิด wizard แล้วเปิด PowerShell หรือ Windows Terminal แบบปกติ โดยชื่อหน้าต่างต้องไม่มีคำว่า Administrator จากนั้นรันคำสั่งเดิมอีกครั้ง"
    exit 1
  fi
}

show_tier_a_workflow() {
  local target="$1"
  say "ทดสอบ $target ใน text control จริงตามลำดับนี้"
  step "วาง caret แล้วกด Win + . ตรวจว่า Picker เปิดใกล้ target และรับ focus"
  step "ค้น heart และ หัวใจ; click ต้องส่งแล้วคง Picker, Shift+Enter ต้องส่งแล้วคง Picker"
  step "Enter ต้องส่งแล้วปิด Picker พร้อมกลับ target เดิม"
  step "เปิดใหม่: Esc ใน Search กลับ Browse และ Esc ถัดไปปิด; Browse กด Esc ครั้งเดียวปิด"
  step "เปิดใหม่แล้วคลิกนอก Picker ต้องปิดทันทีและไม่แย่ง focus กลับ"
  step "เปิดใหม่แล้วพิมพ์ข้อความต่อ ตรวจว่า Picker ปิดและอักขระแรกไม่หาย (Typing Handoff)"
  step "ตรวจว่า target ได้ทั้ง Emoji เดี่ยวและ sequence ซับซ้อน โดยไม่มีข้อความหรือ focus ผิดหน้าต่าง"
}

cat > "$TEST_PAGE" <<'HTML'
<!doctype html>
<html lang="th">
<meta charset="utf-8">
<title>Modern Emoji Picker — Manual Target</title>
<style>
body{font:16px system-ui;margin:32px;max-width:900px}textarea{width:100%;height:220px;font-size:28px}pre{padding:16px;background:#eee;white-space:pre-wrap}
</style>
<h1>พื้นที่ทดสอบ Chrome</h1>
<p>วาง caret ในช่องนี้ แล้วใช้ Modern Emoji Picker ข้อมูลด้านล่างจะแสดง Unicode code points ของข้อความที่ได้รับ</p>
<textarea id="target" autofocus></textarea>
<h2>Unicode code points</h2><pre id="points"></pre>
<script>
const target=document.querySelector('#target'), points=document.querySelector('#points');
function update(){points.textContent=Array.from(target.value).map(c=>'U+'+c.codePointAt(0).toString(16).toUpperCase().padStart(4,'0')).join(' ')}
target.addEventListener('input',update);target.focus();
