declare -a SEQUENCE_CASES=(
  "sequence-single|single code point 😀|😀"
  "sequence-variation-selector|variation selector ❤️|❤️"
  "sequence-skin-tone|skin tone 🙋🏿|🙋🏿"
  "sequence-mixed-tone|mixed tone 🫱🏻‍🫲🏿|🫱🏻‍🫲🏿"
  "sequence-flag|flag 🇹🇭|🇹🇭"
  "sequence-keycap|keycap 1️⃣|1️⃣"
  "sequence-zwj-family|ZWJ family 👨‍👩‍👧|👨‍👩‍👧"
)
for item in "${SEQUENCE_CASES[@]}"; do
  IFS='|' read -r case_id case_name expected <<< "$item"
  step "ส่ง $expected ไป Notepad/Chrome แล้วเทียบ code points กับ sequence ที่คาด"
  record_case 4 "$case_id" "$case_name" "$EVIDENCE_STAGE_4"
done
step "คลิก Emoji ต่างกันอย่างน้อย 10 ตัวอย่างรวดเร็ว ตรวจลำดับปลายทางตรงกับลำดับคลิก"
record_case 4 "queue-rapid-clicks" "rapid clicks ≤ 20 pending" "$EVIDENCE_STAGE_4"
step "สร้าง active + 20 pending แล้วคลิกเพิ่ม ตรวจว่าแสดง queue full และไม่ drop เงียบ"
record_case 4 "queue-full" "queue full" "$EVIDENCE_STAGE_4"
step "ขณะมี active + pending กด Esc ตรวจว่า active จบ, pending ถูกยกเลิก และ focus กลับถูก target"
record_case 4 "queue-dismiss-active" "dismiss ระหว่างส่ง" "$EVIDENCE_STAGE_4"

stage "Clipboard และ target safety"
save_stage_evidence EVIDENCE_STAGE_5 "หลักฐาน Stage 5 เช่น path วิดีโอ/ภาพ, format list หรือ hash:"
say "เปลี่ยน Settings เป็น Paste always เมื่อกรณีต้องบังคับ Temporary Paste และคืนค่าหลังทดสอบ"
warn "ใช้เฉพาะข้อมูลทดสอบที่ไม่สำคัญใน Clipboard แม้ระบบตั้งใจ restore ข้อมูลเดิม"
declare -a CLIPBOARD_CASES=(
  "clipboard-empty|Clipboard ว่าง"
  "clipboard-text|Clipboard Unicode text"
  "clipboard-image|Clipboard image"
  "clipboard-filedrop|Clipboard files (FileDrop)"
  "clipboard-custom|Clipboard custom/private format"
  "clipboard-changed-during-delay|Clipboard เปลี่ยนระหว่าง delay"
  "target-closed-before-validation|target ปิดก่อน validation"
  "target-focus-changed|focus เปลี่ยนไป window อื่น"
  "target-elevated|elevated target จาก non-elevated Picker"
  "explicit-copy|Explicit Copy"
  "clipboard-history|Windows Clipboard History เปิด"
  "clipboard-manager|Clipboard manager ภายนอก"
)
for item in "${CLIPBOARD_CASES[@]}"; do
  IFS='|' read -r case_id case_name <<< "$item"
  step "เตรียมและทดสอบ: $case_name — ตรวจ format/content/focus ก่อนและหลัง ไม่ใช้แค่ Ctrl+V เป็นหลักฐาน"
  record_case 5 "$case_id" "$case_name" "$EVIDENCE_STAGE_5"
done

stage "Privacy และ runtime network 15 นาที"
save_stage_evidence EVIDENCE_STAGE_6 "หลักฐาน packet/firewall audit (path/ชื่อเครื่องมือ) หรือระบุว่าไม่มี:"
NETWORK_REPORT="$RESULT_ROOT/manual-network-$SESSION_ID.json"
NETWORK_LOG="$RESULT_ROOT/manual-network-$SESSION_ID.log"
ensure_picker_running
say "ตัวช่วยจะเก็บ socket observation 15 นาที ระหว่างนี้ให้เปิด/ค้น/preview/Settings/insert หลายครั้ง"
say "อย่าปิด Picker process จนกว่าตัวจับเวลาจะจบ การสังเกต socket ไม่แทน packet capture/firewall audit"
if confirm "พร้อมเริ่มช่วง 15 นาทีหรือไม่?"; then
  pwsh.exe -NoProfile -File "$(cygpath -w "$NETWORK_OBSERVER")" \
    -DurationSeconds 900 \
    -OutputPath "$(cygpath -w "$NETWORK_REPORT")" > "$NETWORK_LOG" 2>&1 &
  monitor_pid=$!
  say "เริ่มแล้ว เวลา $(date '+%H:%M:%S') — กลับมาที่ terminal นี้หลังใช้งานครบ 15 นาที"
  wait "$monitor_pid" || warn "socket observer รายงานข้อผิดพลาด โปรดดู $NETWORK_LOG"
  monitor_pid=""
  say "จบช่วงสังเกตแล้ว หลักฐาน socket: $NETWORK_REPORT"
else
  warn "ข้ามช่วง 15 นาที กรณี privacy ต้องบันทึกเป็นยังไม่ทดสอบ"
fi

PRIVACY_EVIDENCE="$EVIDENCE_STAGE_6; socket=$NETWORK_REPORT"
record_case 6 "privacy-no-outbound" "ไม่มี outbound DNS/TCP/UDP ระหว่าง resident workflow" "$PRIVACY_EVIDENCE"
record_case 6 "privacy-no-telemetry" "ไม่มี update polling/telemetry/analytics/cloud sync" "$PRIVACY_EVIDENCE"
record_case 6 "privacy-no-remote-assets" "ไม่มี remote font/asset call" "$PRIVACY_EVIDENCE"
record_case 6 "privacy-log-disabled" "diagnostic logging ปิด: ไม่มี log content" "$PRIVACY_EVIDENCE"
record_case 6 "privacy-log-enabled-sanitized" "diagnostic logging เปิด: ไม่มีข้อมูลอ่อนไหว" "$PRIVACY_EVIDENCE"

stage "สร้างและตรวจสรุปผล"
say "กำลังสร้าง JSON และ Markdown จากคำตอบที่คุณบันทึก โดยยังไม่แก้ manual matrix"
pwsh.exe -NoProfile -File "$(cygpath -w "$REPORT_WRITER")" \
  -InputPath "$(cygpath -w "$RESULTS_TSV")" \
  -SessionEnvironmentPath "$(cygpath -w "$ENV_FILE")" \
  -OutputDirectory "$(cygpath -w "$RESULT_ROOT")"
say "ผลดิบ: $RESULTS_TSV"
say "ให้ agent review รายงานก่อนนำผลเข้าสู่ docs/qualification/manual-matrices.md"
pause "กด Enter หลังตรวจว่ารายงานถูกสร้างแล้ว"

finish
